use crate::wasi::clocks::wall_clock;

struct Node;

/// Formats a count of seconds since the Unix epoch as `YYYY-MM-DD` (UTC).
///
/// Uses the civil-from-days algorithm (Howard Hinnant), so no date library is
/// needed. The output is always exactly 10 characters: years past 9999 are
/// saturated to `9999-12-31` so the `len(date) == 10` ensure always holds.
fn format_date(secs: u64) -> String {
    let days = (secs / 86_400) as i64;
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    if y > 9999 {
        return "9999-12-31".to_string();
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        RunInfo {
            date: format_date(started),
            started,
        }
    }
}

export!(Node);
